@@ -51,6 +51,7 @@ Usage: hq broker <command>
   restart [all|primary|standby]  Restart the host standby and/or rebuild and
                                   recreate the primary from deployed compose.
                                   Default: all. Never touches litellm or litellm-db.
+  relogin codex [--check-only]   Attended end-to-end device login recovery.
   role <primary|standby> [--json] Print the resolved codex refresh role (read-only).

 Exit codes for `hq broker forward status`:
@@ -861,6 +862,13 @@ main() {
     status) cmd_status "$@" ;;
     forward) cmd_forward "$@" ;;
     restart) cmd_restart "$@" ;;
+    relogin)
+      local broker_src config_src
+      broker_src="$(resolve_oauth_broker_src)" || hq_die "broker source unavailable"
+      config_src="$HQ_LIB_DIR/../../../platform/agent-os-config/src"
+      hq_ensure_python3
+      PYTHONPATH="$broker_src:$config_src${PYTHONPATH:+:$PYTHONPATH}" "$HQ_PYTHON3" -m oauth_broker.relogin "$@"
+      ;;
     role) cmd_role "$@" ;;
     # `--help` is a request, not a usage error: stdout, exit 0 (DOX-03 / F-hq-03).
     -h | --help | help) usage; exit 0 ;;

@@ -85,7 +85,7 @@ def handle_auth_outages(config: Config, assessment: HealthAssessment, *, runner=
             else "unknown (no cached-token deadline reported)"
         )
         recovery = (
-            "codex login --device-auth (admin user)"
+            "hq broker relogin codex (admin user)"
             if provider.startswith("codex")
             else "claude auth login (bridge owner)"
         )
